"use strict";

var FUENTES_INFORME = [
    { archivo: "Manrope-Regular.ttf", nombre: "Manrope", estilo: "normal", datos: "" },
    { archivo: "Manrope-Bold.ttf", nombre: "Manrope", estilo: "bold", datos: "" },
    { archivo: "Manrope-SemiBold.ttf", nombre: "ManropeSemi", estilo: "normal", datos: "" },
    { archivo: "SpaceGrotesk-Bold.ttf", nombre: "SpaceGrotesk", estilo: "bold", datos: "" },
    { archivo: "SpaceMono-Regular.ttf", nombre: "SpaceMono", estilo: "normal", datos: "" },
    { archivo: "SpaceMono-Bold.ttf", nombre: "SpaceMono", estilo: "bold", datos: "" }
];

function cargarFuentesInforme(doc) {
    for (var i = 0; i < FUENTES_INFORME.length; i++) {
        var f = FUENTES_INFORME[i];

        doc.addFileToVFS(f.archivo, f.datos);
        doc.addFont(f.archivo, f.nombre, f.estilo);
    }
}
